-- Programme: Calisthenics for Beginners
insert into public.programs (slug, name, description, goal, level, duration_days, is_premium, is_published)
values ('calisthenics-beginners', 'Calisthenics for Beginners', 'Learn the foundations: push-ups, squats, planks and bridges, step by step.', 'build_strength', 'beginner', 28, true, true)
on conflict (slug) do update set name = excluded.name, description = excluded.description,
  goal = excluded.goal, level = excluded.level, duration_days = excluded.duration_days, is_published = true;
delete from public.program_days where program_id = (select id from public.programs where slug = 'calisthenics-beginners');
insert into public.program_days (program_id, day_number, title, is_rest_day)
values ((select id from public.programs where slug = 'calisthenics-beginners'), 1, 'Week 1: Push and core', false);
