select d.id, v.position, e.id, v.phase::public.workout_phase, v.rounds, v.reps::smallint, v.seconds::smallint, v.rest
from (values
  (1, 'march-in-place', 'warmup', 1, null, 40, 0),
  (2, 'arm-circles', 'warmup', 1, null, 30, 0),
  (3, 'hip-circles', 'warmup', 1, null, 30, 0),
  (4, 'knee-push-up', 'main', 2, 8, null, 30),
  (5, 'glute-bridge', 'main', 2, 12, null, 30),
  (6, 'forearm-plank', 'main', 2, null, 20, 30),
  (7, 'chair-dip', 'main', 2, 8, null, 30),
  (8, 'dead-bug', 'main', 2, 10, null, 30),
  (9, 'hamstring-stretch', 'cooldown', 1, null, 30, 0),
  (10, 'quad-stretch', 'cooldown', 1, null, 30, 0),
  (11, 'childs-pose', 'cooldown', 1, null, 40, 0)
) as v(position, slug, phase, rounds, reps, seconds, rest)
join public.exercises e on e.slug = v.slug
join public.program_days d on d.day_number = 1
